import { Injectable } from '@nestjs/common';
import * as nodePty from '@lydell/node-pty';
import type { IPty } from '@lydell/node-pty';
import { WebuiConfigService } from '../config/webui-config.service';

// Mirrors TmuxService's own allowlist (same idiom as F120's SESSION_NAME_RE
// there): `sessionName` is always server-generated by the time it reaches
// here, but it still lands directly in `tmux`'s argv, so it is validated
// again at this second chokepoint before that happens — cheap insurance
// against a future caller passing something unvalidated through.
const SESSION_NAME_RE = /^wui-[0-9a-f]{12}$/;

export interface PtySpawnOptions {
  sessionName: string;
  cols: number;
  rows: number;
}

/**
 * Spawns the PTY that backs one WebSocket terminal attachment. This never
 * creates a tmux session — `TmuxService.create()` already did that — it
 * only ever *attaches* to a session that must already exist, via
 * `tmux attach-session -d`.
 *
 * CORRECTION to plan.md/the seeded task text, which both say `-D`: real
 * tmux 3.4 has no such flag on `attach-session` at all — `attach-session`'s
 * usage is `[-dErx] [-c working-directory] [-f flags] [-t target-session]`
 * (confirmed both from `tmux attach-session -D` failing with
 * "unknown flag -D" and from `strings` on the tmux binary). `-D` is a
 * `switch-client` flag with an unrelated meaning ("move to the previously
 * current session"); the "detach other clients" flag on `attach-session` is
 * the **lowercase** `-d`. Verified empirically end-to-end: `-D` makes every
 * attach fail immediately (`onExit({exitCode:1})`, zero PTY output ever
 * reaches the socket); `-d` attaches correctly and detaches any other
 * client already on the session, which is the actual desired behavior — a
 * phone reconnecting after a network flap takes over the pane rather than
 * fighting a ghost client over window size (plan.md §7.3's intent, just
 * the wrong-cased flag).
 */
@Injectable()
export class PtyService {
  constructor(private readonly config: WebuiConfigService) {}

  spawn(opts: PtySpawnOptions): IPty {
    if (!SESSION_NAME_RE.test(opts.sessionName)) {
      throw new Error(
        `PtyService: refusing to spawn for invalid session name ${JSON.stringify(opts.sessionName)}`,
      );
    }
    const { tmuxSocket, tmuxConfPath } = this.config.config;
    return nodePty.spawn(
      'tmux',
      [
        '-L',
        tmuxSocket,
        '-f',
        tmuxConfPath,
        'attach-session',
        '-d',
        '-t',
        opts.sessionName,
      ],
      {
        name: 'xterm-256color',
        cols: opts.cols,
        rows: opts.rows,
        env: process.env,
        // LOAD-BEARING QUIRK (F111): with `encoding: null`, the underlying
        // stream never calls `setEncoding`, so at RUNTIME `onData` delivers
        // a raw `Buffer` — even though `@lydell/node-pty`'s `.d.ts` types
        // that callback's parameter as `string`. Trusting the type and
        // treating the payload as a string would silently corrupt binary
        // pane output (e.g. a full-screen redraw split mid multi-byte
        // sequence) with UTF-8 replacement characters. Callers MUST cast at
        // the call site (see `terminal.ws.ts`) rather than trust the type.
        encoding: null,
      },
    );
  }
}
